//Implementa el comaprable
public class Alerta implements Comparable<Alerta> {
    private int codigo;
    private Dispositivo dispositivo;
    private int horaGeneracion;
    private Severidad severidad;
    private String mensaje;
    private boolean atendida;
    private int horaAtencion;
    private int retraso;


    // Constructor vacio
    public Alerta() {
        codigo = 0;
        dispositivo = null;
        horaGeneracion = 0;
        severidad = null;
        mensaje = "";
        atendida = false;
        horaAtencion = -1;
        retraso = 0;
    }


    // Constructor completo
    public Alerta(int codigo, Dispositivo dispositivo, int horaGeneracion, Severidad severidad, String mensaje) {
        this.codigo = codigo;
        this.dispositivo = dispositivo;
        this.horaGeneracion = horaGeneracion;
        this.severidad = severidad;
        this.mensaje = mensaje;
        atendida = false;
        horaAtencion = -1;
        retraso = 0;
    }


    // Getters
    public int getCodigo() {
        return codigo;
    }

    public Dispositivo getDispositivo() {
        return dispositivo;
    }

    public int getHoraGeneracion() {
        return horaGeneracion;
    }

    public Severidad getSeveridad() {
        return severidad;
    }

    public String getMensaje() {
        return mensaje;
    }

    public boolean getAtendida() {
        return atendida;
    }

    public int getHoraAtencion() {
        return horaAtencion;
    }

    public int getRetraso() {
        return retraso;
    }


    // Atender alerta, la marca como atendida, horas transcurridas, retraso, y calcula el crédito
    public double atender(int horaActual) {
        if (atendida) {
            return 0;
        }

        if (severidad == null || dispositivo == null) {
            return 0;
        }

        if (horaActual < horaGeneracion) {
            return 0;
        }

        // Calcula las horas transcurridas
        int horasTranscurridas = horaActual - horaGeneracion;

        // Calcula el retraso segun el plazo
        int horasRetraso = horasTranscurridas - severidad.getPlazo();

        // Si no se excedio el plazo, no hay retraso
        if (horasRetraso < 0) {
            horasRetraso = 0;
        }

        // Guarda los resultados de la atencion
        retraso = horasRetraso;
        horaAtencion = horaActual;
        atendida = true;

        // Calcula el credito segun la severidad
        return retraso * severidad.getCreditoHora();
    }


    // CompareTo
    // Implementa el metodo de Comparable y para Ordenar

    @Override
    public int compareTo(Alerta otra) {

        // Mayor prioridad primero
        if (severidad.getPrioridad() > otra.getSeveridad().getPrioridad()) {
            return -1;
        }
        else if (severidad.getPrioridad() < otra.getSeveridad().getPrioridad()) {
            return 1;
        }

        // Si la prioridad es igual, la mas antigua primero
        if (horaGeneracion < otra.getHoraGeneracion()) {
            return -1;
        }
        else if (horaGeneracion > otra.getHoraGeneracion()) {
            return 1;
        }

        // Si tambien coincide la hora, compara los codigos
        return Integer.compare(codigo, otra.getCodigo());
    }


    // toString

    @Override
    public String toString() {

        String estado;

        if (atendida) {
            estado = "Atendida";
        }
        else {
            estado = "Pendiente";
        }

        String informacion = "Codigo: " + codigo
                + "\nDispositivo: " + dispositivo.getCodigo()
                + "\nHora de generacion: " + horaGeneracion
                + "\nSeveridad: " + severidad.getNombre()
                + "\nMensaje: " + mensaje
                + "\nEstado: " + estado;

        if (atendida) {
            informacion += "\nHora de atencion: " + horaAtencion;
            informacion += "\nHoras de retraso: " + retraso;
        }

        return informacion;
    }
}
